final isLinux = defaultTargetPlatform == TargetPlatform.linux;

final String? playingPath = nowPlaying.path;
final nowPlayingRowVisible = useState(false);
final scrollPixels = scroll.hasClients ? scroll.position.pixels : 0.0;

// Render boxes get correct sizes only after layout; update visibility in
// a post-frame callback so we can conditionally expose the action.
useEffect(() {
  if (!isLinux || !nowPlaying.isPlaying ||
      playingPath == null ||
      playingPath.isEmpty ||
      searchTerm.value.isNotEmpty) {
    nowPlayingRowVisible.value = false;
    return null;
  }

  WidgetsBinding.instance.addPostFrameCallback((_) {
    nowPlayingRowVisible.value = isTrackVisible(playingPath);
  });
  return null;
}, [
  isLinux,
  nowPlaying.isPlaying,
  playingPath,
  searchTerm.value,
  ctrl.currentPath,
  scrollPixels,
]);

final bool shouldExposeNowPlayingJump =
    isLinux &&
        nowPlaying.isPlaying &&
        playingPath != null &&
        playingPath.isNotEmpty &&
        // When search results are shown, the playing row is not part of the
        // folder-list viewport (scrollToTrack is folder-list only).
        searchTerm.value.isEmpty &&
        (() {
          final parent = p.dirname(playingPath);
          if (parent.isEmpty) return false;
          final inCurrentBrowserFolder = ctrl.currentPath == parent;
          return !inCurrentBrowserFolder || !nowPlayingRowVisible.value;
        })();

